arguments.command:
cd /workspace/tmp && python3 - << 'EOF'
import json
req = json.load(open('/workspace/tmp/fail_req.json'))
for ci, case in enumerate(req['cases']):
    routes = set()
    fronts16 = set()
    fronts64 = set()
    puts = queries = saves = loads = 0
    for op in case['ops']:
        name = op[0]
        if name == 'put':
            a = int(op[1], 16); length = op[2]; hop = op[3]
            p = a >> (128 - length) << (128 - length)
            routes.add((p, length))
            if 16 < length <= 64: fronts16.add(p >> 112)
            elif length > 64: fronts64.add(p >> 64)
            puts += 1
        elif name in ('query', 'image_query'):
            queries += len(op[1])
        elif name == 'save':
            saves += 1
        elif name == 'load_saved':
            assert 0 <= op[1] <= saves - 1, ('bad saved index', ci, op)
            loads += 1
        elif name == 'load':
            loads += 1
            d = op[1]
            assert set(d) == {'root','front16','front64','cells','banks','bitmaps','nexthops'}, 'image keys'
            assert len(d['front16']) <= 4096 and len(d['front64']) <= 4096
            assert len(d['cells']) == 11 and all(type(x) is int and 0 <= x <= 131072 for x in d['cells'])
            assert len(d['banks']) == 11
            total = 0
            for bank in d['banks']:
                assert type(bank) is list and len(bank) <= 65536
                for w in bank:
                    assert type(w) is str and len(w) == 64, ('word shape', w)
                total += len(bank)
            assert total <= 65536
            assert len(d['bitmaps']) <= 8193
            for x in d['bitmaps']:
                assert type(x) is str and len(x) == 16, ('bitmap shape', x)
            assert len(d['nexthops']) <= 8192
            for x in d['nexthops']:
                assert type(x) is int and 0 <= x <= 4194302, ('ni bound', x)
        print(ci, name, 'ok')
        if len(routes) > 8192: print('TOO MANY ROUTES', len(routes))
        if puts > 131072: print('TOO MANY PUTS')
        if queries > 131072: print('TOO MANY QUERIES')
        if saves > 3: print('TOO MANY SAVES', saves)
        if loads > 16: print('TOO MANY LOADS', loads)
        if len(fronts16) > 4096 or len(fronts64) > 4096: print('TOO MANY FRONTS')
    print('case', ci, 'ops', len(case['ops']), 'puts', puts, 'queries', queries, 'saves', saves, 'loads', loads, 'routes', len(routes))
EOF
